<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';require_admin();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='add'){ $name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException();$pdo->prepare('INSERT INTO categories(name,status) VALUES(?,"ACTIVE")')->execute([$name]);$success='Category added.';}elseif($action==='toggle'){$pdo->prepare("UPDATE categories SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE category_id=?")->execute([(int)$_POST['id']]);$success='Category status updated.';}elseif($action==='delete'){$pdo->prepare('DELETE FROM categories WHERE category_id=?')->execute([(int)$_POST['id']]);$success='Category deleted.';}}catch(Throwable $e){$error='Could not save the category. It may already exist or be in use.';}}$cats=$pdo->query('SELECT c.*,COUNT(p.product_id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.category_id GROUP BY c.category_id ORDER BY c.name')->fetchAll();$title='Categories';require __DIR__.'/../includes/header.php';?><section class="shell admin-page"><div class="admin-top"><div><span class="eyebrow">STORE STRUCTURE</span><h1>Categories</h1></div><a class="btn btn-outline" href="/admin/dashboard.php">Dashboard</a></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><div class="panel"><form method="post" class="inline-add"><?=csrf_field()?><input type="hidden" name="action" value="add"><input name="name" placeholder="e.g. Smartphones" required><button class="btn btn-primary">Add category</button></form></div><div class="panel"><div class="table-wrap"><table class="pro-table"><tr><th>Category</th><th>Products</th><th>Status</th><th>Actions</th></tr><?php foreach($cats as $c):?><tr><td><strong><?=e($c['name'])?></strong></td><td><?=$c['product_count']?></td><td><?=e($c['status'])?></td><td><div class="action-row"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$c['category_id']?>"><button class="btn btn-small btn-outline"><?=$c['status']==='ACTIVE'?'Hide':'Activate'?></button></form><form method="post" onsubmit="return confirm('Delete this category?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['category_id']?>"><button class="btn btn-small btn-danger">Delete</button></form></div></td></tr><?php endforeach;?></table></div></div></section><?php require __DIR__.'/../includes/footer.php';?>